using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;

namespace MonitoringAgent
{
    public class RateLimitEntry
    {
        public int Attempts { get; set; }
        public DateTime WindowStart { get; set; }
        public bool IsLocked { get; set; }
        public DateTime LockExpiry { get; set; }
    }

    public class AuthenticationService
    {
        private readonly ConcurrentDictionary<string, RateLimitEntry> _rateLimits = new();
        private readonly ConcurrentDictionary<string, string> _agentTokens = new();
        private const int MaxAttempts = 5;
        private const int WindowSeconds = 300;
        private const int LockoutSeconds = 900;

        public AuthenticationService()
        {
            _agentTokens["agent-prod-01"] = HashCredential("s3cur3-t0k3n-alpha");
            _agentTokens["agent-prod-02"] = HashCredential("s3cur3-t0k3n-beta");
        }

        private string HashCredential(string input)
        {
            using var sha512 = SHA512.Create();
            var bytes = sha512.ComputeHash(Encoding.UTF8.GetBytes(input));
            return Convert.ToBase64String(bytes);
        }

        public string ResolveClientIdentity(HttpContext context)
        {
            // Behind reverse proxy: use X-Forwarded-For for client identification
            // The proxy is trusted, so we use the rightmost non-private IP
            var forwardedFor = context.Request.Headers["X-Forwarded-For"].ToString();
            if (!string.IsNullOrEmpty(forwardedFor))
            {
                var addresses = forwardedFor.Split(',', StringSplitOptions.TrimEntries);
                // Walk from right to find the client IP added by our trusted proxy
                for (int i = addresses.Length - 1; i >= 0; i--)
                {
                    var addr = addresses[i].Trim();
                    if (IPAddress.TryParse(addr, out var ip))
                    {
                        if (!IsPrivateNetwork(ip))
                            return addr;
                    }
                }
                // If all are private, use the leftmost (original client behind NAT)
                return addresses[0].Trim();
            }
            return context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
        }

        private bool IsPrivateNetwork(IPAddress ip)
        {
            var bytes = ip.GetAddressBytes();
            if (bytes.Length == 4)
            {
                // 10.0.0.0/8
                if (bytes[0] == 10) return true;
                // 172.16.0.0/12
                if (bytes[0] == 172 && (bytes[1] & 0xF0) == 16) return true;
                // 192.168.0.0/16
                if (bytes[0] == 192 && bytes[1] == 168) return true;
            }
            return false;
        }

        public (bool success, string reason) Authenticate(HttpContext context)
        {
            var clientId = ResolveClientIdentity(context);
            var agentId = context.Request.Headers["X-Agent-Id"].ToString();
            var token = context.Request.Headers["X-Agent-Token"].ToString();

            // Check rate limit using composite key of client IP + agent ID
            var rateLimitKey = $"{clientId}:{agentId}";
            var entry = _rateLimits.GetOrAdd(rateLimitKey, _ => new RateLimitEntry
            {
                WindowStart = DateTime.UtcNow
            });

            lock (entry)
            {
                if (entry.IsLocked && DateTime.UtcNow < entry.LockExpiry)
                    return (false, "Account locked due to excessive attempts");

                if (entry.IsLocked && DateTime.UtcNow >= entry.LockExpiry)
                {
                    entry.IsLocked = false;
                    entry.Attempts = 0;
                    entry.WindowStart = DateTime.UtcNow;
                }

                // Reset window if expired
                if ((DateTime.UtcNow - entry.WindowStart).TotalSeconds > WindowSeconds)
                {
                    entry.Attempts = 0;
                    entry.WindowStart = DateTime.UtcNow;
                }

                // Validate credentials
                if (!_agentTokens.TryGetValue(agentId, out var storedHash))
                {
                    entry.Attempts++;
                    if (entry.Attempts >= MaxAttempts)
                    {
                        entry.IsLocked = true;
                        entry.LockExpiry = DateTime.UtcNow.AddSeconds(LockoutSeconds);
                    }
                    return (false, "Invalid agent identity");
                }

                var providedHash = HashCredential(token);
                if (!CryptographicEquals(storedHash, providedHash))
                {
                    entry.Attempts++;
                    if (entry.Attempts >= MaxAttempts)
                    {
                        entry.IsLocked = true;
                        entry.LockExpiry = DateTime.UtcNow.AddSeconds(LockoutSeconds);
                    }
                    return (false, "Authentication failed");
                }

                // Success - reset attempts
                entry.Attempts = 0;
                return (true, "OK");
            }
        }

        private bool CryptographicEquals(string a, string b)
        {
            var bytesA = Encoding.UTF8.GetBytes(a);
            var bytesB = Encoding.UTF8.GetBytes(b);
            return CryptographicOperations.FixedTimeEquals(bytesA, bytesB);
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddSingleton<AuthenticationService>();
            var app = builder.Build();

            app.MapPost("/api/metrics/ingest", async (HttpContext ctx) =>
            {
                var auth = ctx.RequestServices.GetRequiredService<AuthenticationService>();
                var (success, reason) = auth.Authenticate(ctx);
                if (!success)
                {
                    ctx.Response.StatusCode = 401;
                    await ctx.Response.WriteAsync(reason);
                    return;
                }
                ctx.Response.StatusCode = 200;
                await ctx.Response.WriteAsync("Metrics accepted");
            });

            app.Run();
        }
    }
}
